draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2 - 50, H/2 - 75, 100, 150);
  ctx.strokeRect(W/2 - 50, H/2 - 75, 100, 150);

  // Draw stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 150, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 20);
  ctx.lineTo(W/2 - 150, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 50);
  ctx.lineTo(W/2 - 120, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 50);
  ctx.lineTo(W/2 - 180, H/2 + 70);
  ctx.stroke();

  // Draw wisdom lines
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 - 50 + i * 20, H/2 - 75 + Math.sin(t + i) * 20);
    ctx.lineTo(W/2 - 50 + i * 20, H/2 - 25 + Math.sin(t + i) * 20);
    ctx.stroke();
  }

  ctx.restore();
}
